// ============================================================
// CONFIG – edit these values after import (see README.md)
// ============================================================
return [{ json: {
  LOCATION_ID: 'XTpY4DQ6CrYVvesFdX3K',
  RESTAURANT_GUID: 'ca749399-db34-462a-8792-f6de561b240f', // Craft Mountain Brewing (Toast)
  TIMEZONE: 'America/Denver',
  IGNORE_TEST_MODE: false,      // set true after go-live so Toast Test Mode orders are skipped
  VERIFY_SIGNATURE: false,      // set true once the Toast webhook secret is added below
  TOAST_WEBHOOK_SECRET: '',     // Toast Web > Integrations > Webhooks > subscription > Secret
  MUG_DIGITS: 5,                // "37" -> "00037"
  // GHL "Toast Event Lock" object (primary field unique): each Toast perk event is processed once
  EVENT_LOCK_OBJECT: 'custom_objects.toast_event_locks',
  MEMBER_TAG: 'mug-club-member',   // only contacts with this tag are Mug Club members (guests also have mug numbers)
  // Production URL of workflow 4 (New Member Mug Number) – assigns the mug number to members created from Toast guests
  NEW_MEMBER_WEBHOOK_URL: 'https://n8n.srv1300653.hstgr.cloud/webhook/new-member',
  ALERT_WEBHOOK_URL: 'https://services.leadconnectorhq.com/hooks/XTpY4DQ6CrYVvesFdX3K/webhook-trigger/fef6a874-f832-4a04-ae0a-60a31167e44e',

  // Toast item / discount GUID -> benefit key
  BENEFITS: {
    'e9a3cfc6-b806-4ded-8728-614227c8cb56': 'free_pour',
    'c88b437d-f32d-443d-820b-3082ddd0260d': 'four_pack',    // 50% off 4-Pack
    '9b216070-9c8b-4d37-ae41-fba6bdc33c77': 'initial_pour', // Initial Member Pour
    '983ba063-e991-447f-83ef-9c3ce7ea0f3b': 'mug',          // Special Mug Pricing (24oz at 16oz)
    '14281b9e-6aef-421a-b1c8-00885f4e95c4': 'merch',        // Merchandise 10%
    'c4d8accd-1f31-443d-8689-a202f6e52b64': 'member_mug',   // Member Mug
  },
  // monthly = once per month, once = once ever, log = unlimited (note only)
  BENEFIT_KINDS: { free_pour: 'monthly', four_pack: 'monthly', initial_pour: 'once', mug: 'monthly', merch: 'monthly', member_mug: 'log' },
  BENEFIT_LABELS: { free_pour: 'Free Monthly Pour', four_pack: '50% off 4-Pack', initial_pour: 'Initial Member Pour', mug: 'Special Mug Pricing', merch: 'Merchandise 10%', member_mug: 'Member Mug' },

  // GHL custom field IDs (run the "Helper – List GHL Custom Field IDs" workflow to get them)
  FIELD_IDS: { mugNumber: 'vWklTcHjmQV1tW52XIAb' },
  BENEFIT_FIELDS: {
    free_pour:    { period: 'sfwSQ746eytoaIErT1xL', status: 'nQ1XQVxK7dt5x2jkmzQK', date: 'Kzbwb0nNxFhlcNZoMrvP', orderId: 'd5zGuaAsujwiO4h3KMzm' },
    four_pack:    { period: 'BpyqJNV3NHbz4mdskVzq', status: 'CPdRbUyVL44UpTcIOHzc', date: 'HmCaCCkzQGO0AE69ca22', orderId: 'Qx5rNt0TNh6GF9aZKoFn' },
    initial_pour: { date: 'i9s94p3uVbJ8Gs5IrWHU', orderId: 'QPgwP99xNpVVXWB4w8iY' },
    merch:        { period: 'KKeZG0ZINPUecpSVpyhG', status: 'hUof3kNaxMaSle2hym89', date: '4N9eBmteLZT32n7H26Di', orderId: 'aK57I3miSRJ2xdLBjU8O' },
    mug:          { period: '72x0lCUx388Wko8MGSlC', status: 'wrl8FbQuiPNbEATFZcUY', date: 'NSE4Zsviw6HOoQkQB6t1', orderId: 'SaeAergSBjYbMNjW9eZu' },
  },

  // GHL "Member Perks" pipeline: one card per member, moved after each redemption
  PIPELINE: {
    id: 'ay4k4DUjXvvQaYnmmjIA',
    stages: {
      available: '10497e96-254f-471e-8571-66b59f4b1dc5', // Perks Available
      free_pour: 'f9ba5617-2bbc-42cc-9c8f-3dce1ce5ce22', // Free Pour Used
      four_pack: '73baf16f-e0d2-4d8c-a94b-b076b1b2d28e', // 4-Pack Used
      merch: 'c54cd34a-4063-4b6e-b697-feda5185ca19',         // Merch Used (exactly one perk used: Merch 10%)
      mug: 'b08fd9d0-1167-4faa-843a-153e83149b88',     // Mug Pricing Used (exactly one perk used: Mug Pricing)
      several: '90ed770d-245b-41d6-9224-c261ecce2f65',     // Several Perks Used (2 or 3 of the 4 monthly perks used)
      all: '160674ce-3c8f-4a07-976e-540f94f4fa69',       // All Perks Used (all 4 monthly perks used)
      review: '0e44c91c-4012-4f75-b44a-1adae1a5650a',    // Needs Review
    },
  },
}}];

// Reads the Toast order_updated webhook and outputs one item per benefit found.
// Returns nothing (workflow stops) for normal orders.
const cfg = $('Config').first().json;
const input = $('Toast Webhook').first();
const headers = input.json.headers || {};
let body = input.json.body;
let raw = null;
if (input.binary && input.binary.data) {
  raw = Buffer.from(input.binary.data.data, 'base64').toString('utf8');
  if (!body || typeof body !== 'object') { try { body = JSON.parse(raw); } catch (e) {} }
}
if (!body) return [];

// Optional: verify Toast signature (needs NODE_FUNCTION_ALLOW_BUILTIN=crypto on the n8n server)
if (cfg.VERIFY_SIGNATURE) {
  const crypto = require('crypto');
  const expected = crypto.createHmac('sha256', cfg.TOAST_WEBHOOK_SECRET)
    .update(raw || JSON.stringify(body)).digest('base64');
  if (expected !== headers['toast-signature']) throw new Error('Invalid Toast signature – request rejected');
}

const rid = (body.details && body.details.restaurantGuid) || headers['toast-restaurant-external-id'];
if (cfg.RESTAURANT_GUID && rid && rid !== cfg.RESTAURANT_GUID) return [];

const order = body.details && body.details.order;
if (!order) return [];
if (cfg.IGNORE_TEST_MODE && order.createdInTestMode) return [];

// Tab name -> mug number, padded to MUG_DIGITS ("37", "0037" and "00037" all -> "00037").
// Accepts "37", "#37", "Mug 37", and a name next to it: "37 Manam", "Manam #37", "Testing 37"
// (online orders use the customer name as the tab name). "Table 12", "Seat 4", "Bar 2" are not mug numbers.
const NOT_A_MUG = /\b(?:table|tbl|seat|booth|bar|patio|tab|order|check|party|guests?|pax|room)\s*#?\s*\d+/gi;
const parseMug = (tab) => {
  const s = String(tab || '').replace(NOT_A_MUG, ' ');
  const m = s.match(/^\s*(?:mug\s*)?#?\s*(\d{1,7})(?!\d)/i)
    || s.match(/(?:\bmug\s*#?|#)\s*(\d{1,7})(?!\d)/i)
    || s.match(/(?:^|\s)(\d{1,7})(?=\s*$)/);
  const n = m ? parseInt(m[1], 10) : 0;
  return n ? String(n).padStart(cfg.MUG_DIGITS, '0') : '';
};

const bd = String(order.businessDate || '');
// Calendar day of a Toast timestamp in the brewery's time zone (matches the times shown in the bar site's log)
const denverDay = (iso) => {
  const t = iso ? DateTime.fromISO(String(iso), { setZone: true }) : null;
  return t && t.isValid ? t.setZone(cfg.TIMEZONE).toFormat('yyyy-MM-dd') : '';
};
const period = bd.length === 8 ? `${bd.slice(0, 4)}-${bd.slice(4, 6)}` : '';
const businessDay = bd.length === 8 ? `${bd.slice(0, 4)}-${bd.slice(4, 6)}-${bd.slice(6, 8)}` : '';
const events = [];

for (const check of order.checks || []) {
  const status = String(check.paymentStatus || '').toUpperCase();
  const closed = status === 'PAID' || status === 'CLOSED';
  const mug = parseMug(check.tabName);
  // The day (and month) a perk counts for is the day the check was paid in Denver; Toast's businessDate is only the fallback
  const paidDay = denverDay(check.paidDate || order.paidDate || order.openedDate) || businessDay;
  const checkPeriod = paidDay ? paidDay.slice(0, 7) : period;
  // Webhooks only carry the guest id; "Get Toast Order" fetches name / email / phone when there is no mug number
  const cust = check.customer || {};
  const customerName = [cust.firstName, cust.lastName].filter(Boolean).join(' ');

  const add = (guid, sel, source) => {
    const benefit = guid && cfg.BENEFITS[guid];
    if (!benefit) return;
    const voided = !!(order.voided || order.deleted || check.voided || check.deleted || (sel && sel.voided));
    if (!voided && !closed) return; // wait until the check is paid/closed
    events.push({ json: {
      type: voided ? 'void' : 'redeem',
      benefit,
      benefitKind: cfg.BENEFIT_KINDS[benefit] || 'log',
      mug,
      customerGuid: cust.guid || '',
      customerName, customerEmail: cust.email || '', customerPhone: cust.phone || '',
      tabName: check.tabName || '',
      period: checkPeriod, businessDate: bd, businessDay: paidDay,
      orderGuid: order.guid,
      checkGuid: check.guid,
      selectionGuid: sel ? sel.guid : `${check.guid}-${guid}`,
      itemName: sel ? (sel.displayName || '') : '',
      source,
      displayNumber: check.displayNumber || order.displayNumber || '',
      testMode: !!order.createdInTestMode,
    }});
  };

  for (const sel of check.selections || []) {
    add(sel.item && sel.item.guid, sel, 'item');
    for (const d of sel.appliedDiscounts || []) add(d.discount && d.discount.guid, sel, 'item_discount');
  }
  for (const d of check.appliedDiscounts || []) add(d.discount && d.discount.guid, null, 'check_discount');
}
return events;

// Decides what to do for one benefit event, using the member found in GHL.
// action: update | note | alert | ignore
const cfg = $('Config').first().json;
const ev = { ...$('Build Search').item.json };
let contacts = $json.contacts || [];
// Notes say how the member was found when the tab had no mug number
const out = (o) => ({ json: { ...ev, ...o,
  ...(o.note && ev.matchedBy ? { note: ev.matchedBy === 'new member'
    ? `${o.note} – new member created from Toast order (joins the Mug Club)`
    : `${o.note} – matched by ${ev.matchedBy} (no mug number on tab)` } : {}) } });
const label = cfg.BENEFIT_LABELS[ev.benefit] || ev.benefit;
const alertText = (msg) =>
  `[Craft Mountain perks] ${msg} | ${label} | tab "${ev.tabName}" | check #${ev.displayNumber} | business date ${ev.businessDay} | Toast order ${ev.orderGuid}`;

// Member picked by "Resolve Member" (by mug number, email, phone, name, or created from the Toast guest)
const mugOf = (c) => {
  const f = (c.customFields || []).find(x => x.id === cfg.FIELD_IDS.mugNumber);
  return f && f.value ? String(f.value).trim() : '';
};
ev.matchedBy = $json.matchedBy || '';
if (!ev.mug) {
  if (contacts.length === 1) {
    ev.mug = mugOf(contacts[0]); // empty for a member just created – workflow 4 assigns the number
  } else if (contacts.length > 1) {
    return ev.type === 'redeem'
      ? out({ action: 'alert', alertType: 'ambiguous_name', alertText: alertText(`No mug number on the tab and ${contacts.length} members match "${ev.tabName || ev.customerName}" – add the mug number in GHL by hand`) })
      : out({ action: 'ignore' });
  } else {
    return ev.type === 'redeem'
      ? out({ action: 'alert', alertType: 'no_mug', alertText: alertText('Benefit rung up WITHOUT a mug number in the tab name (no member matched by name, email or phone)') })
      : out({ action: 'ignore' });
  }
}
if (contacts.length === 0) {
  return ev.type === 'redeem'
    ? out({ action: 'alert', alertType: 'no_member', alertText: alertText(`No member found with mug number ${ev.mug}`) })
    : out({ action: 'ignore' });
}
if (contacts.length > 1) {
  return out({ action: 'alert', alertType: 'duplicate_mug', alertText: alertText(`More than one member has mug number ${ev.mug} – fix in GHL`) });
}

const c = contacts[0];
const name = [c.firstName, c.lastName].filter(Boolean).join(' ') || c.contactName || c.email || c.id;
const cf = {};
for (const f of c.customFields || []) cf[f.id] = f.value;
const val = (id) => {
  const v = cf[id];
  if (v === undefined || v === null) return '';
  return Array.isArray(v) ? v.join(',') : String(v);
};
const f = cfg.BENEFIT_FIELDS[ev.benefit] || {};
// Mug Club members only. A guest found through the Toast guest lookup or by name (or just created) joins the club:
// the perk is recorded and workflow 4 adds the member tag. A guest rung up by mug number alone is flagged.
const isMember = (c.tags || []).includes(cfg.MEMBER_TAG);
const enroll = !isMember && !!ev.matchedBy;
if (!isMember && !enroll && ev.type === 'redeem') {
  return out({ contactId: c.id, memberName: name, action: 'alert', alertType: 'not_member',
    alertText: alertText(`${name} (mug ${ev.mug}) is not a Mug Club member – perk not recorded`) });
}
const base = { contactId: c.id, memberName: name, memberFields: cf, enroll }; // memberFields: perk statuses before this update

// ---- Monthly perks (free pour, 4-pack, merch, mug pricing) ----
if (ev.benefitKind === 'monthly') {
  const sameOrder = val(f.orderId) === ev.orderGuid;
  if (ev.type === 'void') {
    if (!sameOrder) return out({ ...base, action: 'ignore' });
    return out({ ...base, action: 'update',
      fieldUpdates: [
        { id: f.status, field_value: 'Available' },
        { id: f.period, field_value: '' },
        { id: f.orderId, field_value: '' },
      ],
      note: `${label} REVERTED (voided in Toast) – period ${ev.period} – Toast order ${ev.orderGuid}` });
  }
  if (sameOrder) return out({ ...base, action: 'ignore' }); // Toast re-sent the same order
  if (val(f.period) === ev.period && val(f.status) === 'Redeemed') {
    return out({ ...base, action: 'alert', alertType: 'double',
      alertText: alertText(`${name} (mug ${ev.mug}) already used ${label} for ${ev.period}`) });
  }
  return out({ ...base, action: 'update',
    fieldUpdates: [
      { id: f.period, field_value: ev.period },
      { id: f.status, field_value: 'Redeemed' },
      { id: f.date, field_value: ev.businessDay },
      { id: f.orderId, field_value: ev.orderGuid },
    ],
    note: `${label} redeemed – period ${ev.period} – check #${ev.displayNumber} – Toast order ${ev.orderGuid}` });
}

// ---- One-time perks (initial member pour) ----
if (ev.benefitKind === 'once') {
  const sameOrder = val(f.orderId) === ev.orderGuid;
  if (ev.type === 'void') {
    if (!sameOrder) return out({ ...base, action: 'ignore' });
    return out({ ...base, action: 'update',
      fieldUpdates: [{ id: f.date, field_value: '' }, { id: f.orderId, field_value: '' }],
      note: `${label} REVERTED (voided in Toast) – Toast order ${ev.orderGuid}` });
  }
  if (sameOrder) return out({ ...base, action: 'ignore' });
  if (val(f.date)) {
    return out({ ...base, action: 'alert', alertType: 'double',
      alertText: alertText(`${name} (mug ${ev.mug}) already received the ${label} on ${val(f.date).slice(0, 10)}`) });
  }
  return out({ ...base, action: 'update',
    fieldUpdates: [{ id: f.date, field_value: ev.businessDay }, { id: f.orderId, field_value: ev.orderGuid }],
    note: `${label} redeemed – check #${ev.displayNumber} – Toast order ${ev.orderGuid}` });
}

// ---- Unlimited perks (member mug): log a note once per item ----
if (ev.type === 'void') return out({ ...base, action: 'ignore' });
const seen = $getWorkflowStaticData('global');
seen.logged = seen.logged || {};
if (seen.logged[ev.selectionGuid]) return out({ ...base, action: 'ignore' });
seen.logged[ev.selectionGuid] = Date.now();
const cutoff = Date.now() - 60 * 24 * 3600 * 1000; // keep 60 days
for (const k of Object.keys(seen.logged)) if (seen.logged[k] < cutoff) delete seen.logged[k];
return out({ ...base, action: 'note',
  note: `${label} used – check #${ev.displayNumber} – business date ${ev.businessDay} – Toast order ${ev.orderGuid}` });

// Picks the member's pipeline stage from the four monthly perk statuses (after this update).
// none used -> Perks Available | exactly one -> that perk's stage | two or three -> Several Perks Used | all four -> All Perks Used
const cfg = $('Config').first().json;
const ev = $('Ready').item.json; // includes the mug number of a just-enrolled member
const cf = { ...(ev.memberFields || {}) };
for (const u of ev.fieldUpdates || []) cf[u.id] = u.field_value;
const bf = cfg.BENEFIT_FIELDS;
const used = {
  free_pour: cf[bf.free_pour.status] === 'Redeemed',
  four_pack: cf[bf.four_pack.status] === 'Redeemed',
  merch: cf[bf.merch.status] === 'Redeemed',
  mug: cf[bf.mug.status] === 'Redeemed',
};
const count = Object.values(used).filter(Boolean).length;
const s = cfg.PIPELINE.stages;
const set = (id) => id && !String(id).startsWith('REPLACE'); // stages not created in GHL yet fall back to the old behavior
let stageId = s.available;
if (count === 4) stageId = s.all;
else if (count >= 2) stageId = set(s.several) ? s.several : s.all;
else if (count === 1) {
  const only = Object.keys(used).find((k) => used[k]);
  stageId = set(s[only]) ? s[only] : s.available;
}
return { json: { contactId: ev.contactId, name: `${ev.memberName} – Mug ${ev.mug}`, stageId } };

// Double redemptions by a known member go to the "Needs Review" stage.
const cfg = $('Config').first().json;
return $input.all()
  .filter(i => i.json.alertType === 'double' && i.json.contactId)
  .map(i => ({ json: { contactId: i.json.contactId, name: `${i.json.memberName} – Mug ${i.json.mug}`, stageId: cfg.PIPELINE.stages.review } }));

// One GHL "Perk Log" record per redemption, void, note or alert (Toast re-sends are skipped).
const labels = $('Config').first().json.BENEFIT_LABELS;
const EVENT_NAMES = { redeem: 'Redeemed', used: 'Used', void: 'Voided', double: 'Double use', no_member: 'Unknown mug', no_mug: 'No mug on tab', duplicate_mug: 'Duplicate mug', ambiguous_name: 'Name matches several members', not_member: 'Not a member' };
return $input.all()
  .filter(i => i.json.action !== 'ignore')
  .map(({ json: e }) => {
    const event = e.action === 'update' ? (e.type === 'void' ? 'void' : 'redeem') : e.action === 'note' ? 'used' : (e.alertType || 'alert');
    const perk = labels[e.benefit] || e.benefit;
    return { json: {
      contactId: e.contactId || '',
      properties: {
        title: `#${e.mug || '–'} · ${perk} · ${EVENT_NAMES[event] || event}`,
        logged_at: new Date().toISOString(),
        business_day: e.businessDay || '',
        mug: e.mug || '',
        member: e.memberName || '',
        perk,
        event,
        toast_order_id: e.orderGuid || '',
        check_number: String(e.displayNumber || ''),
        detail: e.alertText || e.note || '',
      },
    } };
  });

// Alerts without a known member (no mug / unknown mug) are logged but not linked.
const rows = $('Build Log Row').all();
return $input.all()
  .map((item, i) => ({ json: { recordId: (item.json.record || item.json).id, contactId: rows.at(i).json.contactId } }))
  .filter(i => i.json.recordId && i.json.contactId);

// Adds the guest's name / email / phone from the full Toast order (empty if the lookup failed).
const ev = { ...$('Guest Lookup Needed?').item.json };
const check = ($json.checks || []).find(c => c.guid === ev.checkGuid) || {};
const cust = check.customer || {};
ev.customerEmail = cust.email || '';
ev.customerPhone = cust.phone || '';
ev.customerFirstName = cust.firstName || '';
ev.customerLastName = cust.lastName || '';
ev.customerName = [cust.firstName, cust.lastName].filter(Boolean).join(' ');
return { json: ev };

// GHL search for the member: exact mug number, or (no mug) members matching email, phone or name.
const cfg = $('Config').first().json;
const ev = $json;
const mugFilter = (operator, value) => ({ field: 'customFields.' + cfg.FIELD_IDS.mugNumber, operator, ...(value ? { value } : {}) });
const query = ev.mug ? '' : (ev.customerEmail || ev.customerPhone || String(ev.tabName || '').trim() || ev.customerName);
const searchBody = ev.mug
  ? { locationId: cfg.LOCATION_ID, page: 1, pageLimit: 5, filters: [mugFilter('eq', ev.mug)] }
  : query
    ? { locationId: cfg.LOCATION_ID, page: 1, pageLimit: 10, query, filters: [mugFilter('exists')] }
    : { locationId: cfg.LOCATION_ID, page: 1, pageLimit: 1, filters: [mugFilter('eq', `no-mug-${ev.orderGuid}`)] };
return { json: { ...ev, searchBody } };

// Picks the member for this event and decides whether GHL needs a new contact or missing details.
// saveAction: create (no member matched, Toast guest has email/phone) | update (fill empty email/phone) | none
const cfg = $('Config').first().json;
const ev = $('Build Search').item.json;
const found = $json.contacts || [];
const mugOf = (c) => {
  const f = (c.customFields || []).find(x => x.id === cfg.FIELD_IDS.mugNumber);
  return f && f.value ? String(f.value).trim() : '';
};
const words = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim().split(' ').filter(Boolean);
const fullName = (s) => { const w = words(s); return w.length >= 2 ? w.sort().join(' ') : ''; }; // first name alone never matches
const phone10 = (s) => String(s || '').replace(/\D/g, '').slice(-10);
const hasPhone = phone10(ev.customerPhone).length === 10;
const matchOf = (c) => {
  if (ev.customerEmail && String(c.email || '').toLowerCase() === ev.customerEmail.toLowerCase()) return 'email';
  if (hasPhone && phone10(c.phone) === phone10(ev.customerPhone)) return 'phone';
  const member = fullName(`${c.firstName || ''} ${c.lastName || ''}`);
  if (member && (member === fullName(ev.tabName) || member === fullName(ev.customerName))) return 'name';
  return '';
};
const none = { saveAction: 'none', saveBody: {} };
if (ev.mug) return { json: { contacts: found, matchedBy: '', ...none } };

const hits = found.filter(c => mugOf(c) && matchOf(c));
if (hits.length === 1) {
  // Fill in email / phone the member is missing in GHL (never overwrite)
  const c = hits[0];
  const saveBody = {};
  if (ev.customerEmail && !c.email) saveBody.email = ev.customerEmail;
  if (hasPhone && !c.phone) saveBody.phone = ev.customerPhone;
  return { json: { contacts: hits, matchedBy: matchOf(c), contactId: c.id,
    ...(Object.keys(saveBody).length ? { saveAction: 'update', saveBody } : none) } };
}
if (hits.length > 1) return { json: { contacts: hits, matchedBy: '', ...none } };

// No member: create one from the Toast guest (only with an email or phone, never from a name alone)
if (ev.type === 'redeem' && (ev.customerEmail || hasPhone)) {
  return { json: { contacts: [], matchedBy: 'new member', saveAction: 'create', saveBody: {
    locationId: cfg.LOCATION_ID,
    firstName: ev.customerFirstName || '',
    lastName: ev.customerLastName || '',
    ...(ev.customerEmail ? { email: ev.customerEmail } : {}),
    ...(hasPhone ? { phone: ev.customerPhone } : {}),
    source: 'Toast order',
    // no tags here: GHL upsert replaces ALL tags, which would remove mug-club-member from an existing contact.
    // Workflow 4 adds mug-club-member + mug-assigned (without touching other tags).
  } } };
}
return { json: { contacts: [], matchedBy: '', ...none } };

// Created contact becomes the member for this event; updated members keep their search data.
const r = $('Save Guest to GHL?').item.json;
if (r.saveAction !== 'create') return { json: r };
const contact = $json.contact || {};
return { json: { ...r, contacts: contact.id ? [contact] : [], contactId: contact.id, newMember: !!contact.id } };

// Event claimed (or the lock itself failed for another reason): continue with the event.
// A duplicate claim means another run already has this event: stop here.
const err = JSON.stringify($json.error || '');
if (/duplicate|unique|already exist/i.test(err)) return null;
return { json: $('Parse Toast Order').item.json };

// The event after enrollment: a member created from a Toast order now carries the mug number from workflow 4.
const ev = $('Decide Action').item.json;
const mug = $json && $json.mug ? String($json.mug) : ev.mug;
return { json: { ...ev, mug } };
